#!/bin/sh
set -eu
BASE=/data/mi-gw2-post-init
HOOK=/data/scripts/post_init.sh
[ "$(id -u)" = 0 ] || { echo 'Run as root.' >&2; exit 1; }
STAMP=$(date +%Y%m%d-%H%M%S)-$PPID
mkdir -p "$BASE/backups/$STAMP" /data/scripts
if [ -e "$HOOK" ]; then
    [ ! -L "$HOOK" ] || { echo 'Refusing a symlink post_init.sh.' >&2; exit 1; }
    cp -p "$HOOK" "$BASE/backups/$STAMP/post_init.sh"
fi
cat > "$HOOK.new" <<'EOF'
#!/bin/sh
# MI-GW2-POST-INIT-API: 1
# Emergency stock-only manifest generated by restore-stock.sh.
# BEGIN MI-GW2 POST-INIT STOCK ANCHOR
/bin/fw_manager.sh -r
RC=$?
mkdir -p /tmp/mi-gw2-post-init
if [ "$RC" -eq 0 ]; then
    touch /tmp/mi-gw2-post-init/stock.ready
else
    touch /tmp/mi-gw2-post-init/stock.failed
fi
exit "$RC"
# END MI-GW2 POST-INIT STOCK ANCHOR
EOF
chmod 755 "$HOOK.new"
sh -n "$HOOK.new"
mv -f "$HOOK.new" "$HOOK"
sync
echo "POST_INIT_STOCK_ONLY_RESTORED backup=$STAMP"
